import { ArrowUpRight } from "lucide-react"
import { galleryItems } from "@/lib/gallery-data"
import { instagramDmUrl } from "@/lib/site-config"

export function GalleryGrid() {
  return (
    <div className="[column-fill:_balance] columns-1 gap-4 sm:columns-2 lg:columns-3">
      {galleryItems.map((item, i) => {
        // Vary heights slightly for an editorial, masonry rhythm.
        const ratios = ["aspect-[4/3]", "aspect-[3/4]", "aspect-square", "aspect-[4/5]"]
        const ratio = ratios[i % ratios.length]
        return (
          <a
            key={i}
            href={instagramDmUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="group relative mb-4 block break-inside-avoid overflow-hidden rounded-xl border border-border bg-card"
          >
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={item.src || "/placeholder.svg"}
              alt={item.title}
              className={`w-full ${ratio} object-cover transition-transform duration-500 ease-out group-hover:scale-[1.04]`}
            />
            <div className="absolute inset-0 bg-gradient-to-t from-background/85 via-background/10 to-transparent opacity-0 transition-opacity duration-300 group-hover:opacity-100" />
            <div className="absolute inset-x-0 bottom-0 flex translate-y-2 items-center justify-between p-4 opacity-0 transition-all duration-300 group-hover:translate-y-0 group-hover:opacity-100">
              <span className="font-display text-sm font-semibold text-foreground">{item.title}</span>
              <span className="inline-flex items-center gap-1 text-xs font-medium text-accent">
                Commission
                <ArrowUpRight className="h-3.5 w-3.5" aria-hidden="true" />
              </span>
            </div>
          </a>
        )
      })}
    </div>
  )
}
